<style>[x-cloak]{display:none!important}.admin-table-loading{opacity:.55;pointer-events:none}.admin-sort{border:0;background:transparent;color:inherit;font:inherit;font-weight:600;cursor:pointer;padding:0}.admin-sort:hover{color:var(--admin-blue)}.admin-sort-icon{font-size:11px;margin-left:3px}.admin-table-error{background:#fef3f2;color:#b42318;border-radius:5px;padding:10px 12px;margin-bottom:15px}.user-status-cell,.user-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.user-status-toggle,.user-archive-button{cursor:pointer!important;pointer-events:auto!important;touch-action:manipulation}</style>
