    <div class="table-wrap" x-bind:class="loading ? 'admin-table-loading' : ''"><table class="table"><thead><tr><th><button class="admin-sort" type="button" x-on:click="sortBy('name')">User <span class="admin-sort-icon" x-text="sortIcon('name')"></span></button></th><th>Contact</th><th><button class="admin-sort" type="button" x-on:click="sortBy('role')">Role <span class="admin-sort-icon" x-text="sortIcon('role')"></span></button></th><th>Profile</th><th><button class="admin-sort" type="button" x-on:click="sortBy('status')">Status <span class="admin-sort-icon" x-text="sortIcon('status')"></span></button></th><th>Actions</th></tr></thead><tbody><template x-for="user in rows" :key="user.id"><tr><td><strong x-text="user.display_name"></strong><br><span class="muted" x-text="user.wellsharp_id"></span></td><td><span x-text="user.email"></span><br><small class="muted" x-text="user.phone"></small></td><td><span x-text="user.role"></span><template x-if="user.proctor_id"><br><small class="muted">ID: <span x-text="user.proctor_id"></span></small></template></td><td><span x-text="user.birthday"></span><br><small class="muted" x-text="user.location"></small></td><td><div class="user-status-cell"><template x-if="user.can_toggle_status"><button class="btn secondary small user-status-toggle" type="button" x-on:click.prevent="toggleStatus(user)" x-bind:disabled="user.statusSaving" x-bind:aria-busy="user.statusSaving ? 'true' : 'false'" x-text="user.statusSaving ? 'Updating...' : (user.status === 'active' ? 'Deactivate' : 'Activate')"></button></template><template x-if="!user.can_toggle_status"><span class="badge" x-bind:class="user.status" x-text="user.status_label"></span></template></div></td><td><div class="user-actions"><a x-bind:href="user.view_url">View</a><template x-if="user.can_archive"><button class="btn secondary small user-archive-button" type="button" x-on:click.prevent="archiveUser(user)" x-bind:disabled="user.archiving" x-bind:aria-busy="user.archiving ? 'true' : 'false'" x-text="user.archiving ? 'Updating...' : 'Archive'"></button></template></div></td></tr></template><tr x-show="!loading && rows.length === 0" x-cloak><td colspan="6" class="muted">No users found.</td></tr></tbody></table></div>
