<script>
    window.userTable = function (endpoint, initialRows, initialMeta) {
        return { endpoint, rows: initialRows || [], meta: initialMeta || { current_page: 1, last_page: 1, total: 0, from: null, to: null }, search: @js($search), roleId: @js((string) $roleId), status: @js($status), sort: 'created_at', direction: 'desc', loading: false, error: '', request: null,
            hasFilters() { return this.search || this.roleId || this.status; }, clearFilters() { this.search = ''; this.roleId = ''; this.status = ''; this.load(1); }, sortIcon(field) { return this.sort === field ? (this.direction === 'asc' ? '▲' : '▼') : '↕'; }, sortBy(field) { if (this.sort === field) this.direction = this.direction === 'asc' ? 'desc' : 'asc'; else { this.sort = field; this.direction = 'asc'; } this.load(1); },
            async load(page) { page = Math.max(1, page || 1); if (this.request) this.request.abort(); this.request = new AbortController(); const params = new URLSearchParams({ page, sort: this.sort, direction: this.direction }); if (this.search) params.set('search', this.search); if (this.roleId) params.set('role_id', this.roleId); if (this.status) params.set('status', this.status); this.loading = true; this.error = ''; try { const response = await fetch(this.endpoint + '?' + params.toString(), { headers: { Accept: 'application/json' }, signal: this.request.signal }); if (!response.ok) throw new Error('User search failed'); const payload = await response.json(); this.rows = payload.data; this.meta = payload.meta; } catch (error) { if (error.name !== 'AbortError') this.error = 'Users could not be loaded. Try again.'; } finally { this.loading = false; } },
            async disableUser(user) { if (!user.can_disable || user.disabling || user.archiving) return; user.disabling = true; this.error = ''; try { const response = await fetch(user.disable_url, { method: 'PATCH', credentials: 'same-origin', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', 'X-Requested-With': 'XMLHttpRequest' } }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || 'User status could not be updated.'); user.status = payload.status; user.status_label = payload.status_label; user.can_disable = false; user.can_archive = false; } catch (exception) { this.error = exception.message || 'User status could not be updated.'; } finally { user.disabling = false; } },
            async toggleStatus(user) { if (!user.can_toggle_status || user.statusSaving || user.archiving) return; user.statusSaving = true; this.error = ''; const status = user.status === 'active' ? 'disabled' : 'active'; try { const response = await fetch(user.status_url, { method: 'PATCH', credentials: 'same-origin', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ status }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || 'User status could not be updated.'); user.status = payload.status; user.status_label = payload.status_label; } catch (exception) { this.error = exception.message || 'User status could not be updated.'; } finally { user.statusSaving = false; } },
            async archiveUser(user) { if (!user.can_archive || user.archiving || user.statusSaving) return; user.archiving = true; this.error = ''; try { const response = await fetch(user.archive_url, { method: 'PATCH', credentials: 'same-origin', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', 'X-Requested-With': 'XMLHttpRequest' } }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || 'User could not be archived.'); user.status = payload.status; user.status_label = payload.status_label; user.can_archive = false; user.can_toggle_status = false; } catch (exception) { this.error = exception.message || 'User could not be archived.'; } finally { user.archiving = false; } }
        };
    };
</script>
